const statusMap = {
  pending:{label:"Pending", cls:"badge-pending"},
  progress:{label:"In Progress", cls:"badge-progress"},
  resolved:{label:"Resolved", cls:"badge-resolved"}
};
const sevMap = {
  low:{label:"Low Severity", cls:"sev-low", icon:"fa-circle-check"},
  medium:{label:"Medium Severity", cls:"sev-medium", icon:"fa-triangle-exclamation"},
  high:{label:"High Severity", cls:"sev-high", icon:"fa-circle-exclamation"}
};

function imgOrPlaceholder(img, title, svgKey){
  if(img) return `<img src="${img}" alt="${title}">`;
  if(svgKey) return svgFor(svgKey, title);
  return `<div class="img-placeholder"><i class="fa-solid fa-image"></i><span>No photo available</span></div>`;
}

