function svgFor(key, title){
  const svg = potholeSVGs[key] || potholeSVGs.basic;
  return `<div class="svg-illustration" role="img" aria-label="${title}">${svg}</div>`;
}

function reportCard(r){
  const s = statusMap[r.status], sv = sevMap[r.severity];
  return `<div class="report-card" onclick="openReportModal(${r.id})">
    <div class="report-img">
      ${imgOrPlaceholder(r.img, r.title, r.svgKey)}
      <span class="badge ${s.cls}">${s.label}</span>
    </div>
    <div class="report-body">
      <span class="severity-tag ${sv.cls}"><i class="fa-solid ${sv.icon}"></i> ${sv.label}</span>
      <h4>${r.title}</h4>
      <p>${r.desc.slice(0,90)}${r.desc.length>90?'…':''}</p>
      <div class="report-meta">
        <span><i class="fa-solid fa-location-dot"></i> ${r.location}</span>
        <span><i class="fa-regular fa-calendar"></i> ${r.date}</span>
      </div>
    </div>
  </div>`;
}

/* render recent reports (home page) - first 3 */
document.getElementById('recentReportsGrid').innerHTML = reportsData.slice(0,6).map(reportCard).join('');

/* render dashboard activity */
document.getElementById('dashActivity').innerHTML = reportsData.slice(0,4).map(r=>{
  const s = statusMap[r.status];
  return `<div class="activity-row">
    <img src="${r.img}" alt="">
    <div class="activity-info">
      <h4>${r.title}</h4>
      <span><i class="fa-solid fa-location-dot"></i> ${r.location} &nbsp;·&nbsp; ${r.date}</span>
    </div>
    <span class="badge ${s.cls}" style="position:static;">${s.label}</span>
  </div>`;
}).join('');

/* ===== REPORTS PAGE FILTER/SEARCH/SORT ===== */
let currentFilter = 'all';
const PAGE_SIZE = 6;
let currentPage = 1;

function renderReports(){
  const q = (document.getElementById('searchInput').value || '').toLowerCase();
  const sort = document.getElementById('sortSelect').value;
  let data = reportsData.filter(r=>{
    const matchFilter = currentFilter==='all' || r.status===currentFilter;
    const matchSearch = r.location.toLowerCase().includes(q) || r.desc.toLowerCase().includes(q) || r.title.toLowerCase().includes(q);
    return matchFilter && matchSearch;
  });
  data = [...data];
  if(sort==='oldest') data.reverse();

  const totalPages = Math.max(1, Math.ceil(data.length / PAGE_SIZE));
  if(currentPage > totalPages) currentPage = totalPages;
  if(currentPage < 1) currentPage = 1;

  const start = (currentPage - 1) * PAGE_SIZE;
  const pageData = data.slice(start, start + PAGE_SIZE);

  document.getElementById('allReportsGrid').innerHTML = pageData.length
    ? pageData.map(reportCard).join('')
    : '<p style="color:#6B7A90;text-align:center;grid-column:1/-1;padding:40px 0;">No reports match your search.</p>';

  renderPagination(totalPages);
}

function renderPagination(totalPages){
  const el = document.getElementById('paginationControls');
  if(totalPages <= 1){ el.innerHTML = ''; return; }
  let html = '';
  for(let i=1; i<=totalPages; i++){
    html += `<button class="${i===currentPage?'active':''}" onclick="goToPage(${i})">${i}</button>`;
  }
  const nextDisabled = currentPage >= totalPages;
  html += `<button onclick="goToPage(${currentPage+1})" ${nextDisabled?'disabled style="opacity:0.4;cursor:not-allowed;"':''}><i class="fa-solid fa-chevron-right"></i></button>`;
  el.innerHTML = html;
}

function goToPage(p){
  currentPage = p;
  renderReports();
  document.querySelector('.reports-toolbar').scrollIntoView({behavior:'smooth', block:'start'});
}

function setFilter(f){
  currentFilter = f;
  currentPage = 1;
  document.querySelectorAll('#filterPills .pill').forEach(p=>p.classList.toggle('active', p.dataset.filter===f));
  renderReports();
}

renderReports();

/* ===== REPORT DETAIL MODAL ===== */
function openReportModal(id){
  const r = reportsData.find(x=>x.id===id);
  if(!r) return;
  const s = statusMap[r.status], sv = sevMap[r.severity];
  document.getElementById('modalImgWrap').innerHTML = imgOrPlaceholder(r.img, r.title, r.svgKey) + `<span class="badge ${s.cls}" id="modalBadge"></span>`;
  document.getElementById('modalBadge').textContent = s.label;
  document.getElementById('modalSeverity').innerHTML = `<i class="fa-solid ${sv.icon}"></i> ${sv.label}`;
  document.getElementById('modalSeverity').className = 'severity-tag ' + sv.cls;
  document.getElementById('modalTitle').textContent = r.title;
  document.getElementById('modalDesc').textContent = r.desc;
  document.getElementById('modalReporter').textContent = r.reporter;
  document.getElementById('modalLocation').textContent = r.location;
  document.getElementById('modalDate').textContent = r.date;
  document.getElementById('modalSeverityLabel').textContent = sv.label;
  document.getElementById('reportModal').classList.add('show');
  document.body.style.overflow = 'hidden';
}
function closeReportModal(){
  document.getElementById('reportModal').classList.remove('show');
  document.body.style.overflow = '';
}

/* ===== NAVIGATION ===== */
let isLoggedIn = false;
let pendingPage = null;

function goTo(page){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.getElementById('page-'+page).classList.add('active');
  document.querySelectorAll('.nav-links a').forEach(a=>a.classList.toggle('active', a.dataset.page===page));
  document.getElementById('mainFooter').style.display = (page==='home') ? 'block' : 'none';
  document.getElementById('navLinks').classList.remove('open');
  window.scrollTo({top:0, behavior:'smooth'});
}

/* Pages that require an account: reporting, uploading, dashboard, profile, notifications */
const protectedPages = ['report-form','dashboard','profile','notifications'];

function protectedGoTo(page){
  if(isLoggedIn || !protectedPages.includes(page)){
    goTo(page);
  } else {
    pendingPage = page;
    goTo('login');
  }
}

/* ===== AUTH FLOW ===== */
/* ===== AUTH FLOW & API INTEGRATION ===== */
let currentUser = window.api.getCurrentUser();
if (currentUser && window.api.getAuthToken()) {
  isLoggedIn = true;
  document.getElementById('loggedOutActions').style.display = 'none';
  document.getElementById('loggedInActions').style.display = 'inline-flex';
}

async function loginUser(){
  const idValue = document.getElementById('loginId').value.trim();
  const passValue = document.getElementById('loginPass').value;
  const errorEl = document.getElementById('loginError');

  try {
    const res = await window.api.login({ email: idValue, password: passValue });
    window.api.setAuthToken(res.token);
    window.api.setCurrentUser(res.user);
    isLoggedIn = true;
    currentUser = res.user;
    document.getElementById('loggedOutActions').style.display = 'none';
    document.getElementById('loggedInActions').style.display = 'inline-flex';
    if(errorEl) errorEl.style.display = 'none';
    goTo(pendingPage || 'dashboard');
    pendingPage = null;
  } catch (err) {
    if(errorEl) {
      errorEl.textContent = err.message || 'Invalid credentials';
      errorEl.style.display = 'block';
    }
  }
}

async function registerUser(){
  const name = document.getElementById('regName').value.trim();
  const email = document.getElementById('regEmail').value.trim();
  const pass = document.getElementById('regPass').value;
  const pass2 = document.getElementById('regPass2').value;
  const errorEl = document.getElementById('registerError');

  if(pass !== pass2){
    document.getElementById('matchError').style.display = 'block';
    return;
  }

  try {
    const res = await window.api.register({ name, email, password: pass });
    window.api.setAuthToken(res.token);
    window.api.setCurrentUser(res.user);
    isLoggedIn = true;
    currentUser = res.user;
    document.getElementById('loggedOutActions').style.display = 'none';
    document.getElementById('loggedInActions').style.display = 'inline-flex';
    if(errorEl) errorEl.style.display = 'none';
    goTo(pendingPage || 'dashboard');
    pendingPage = null;
  } catch (err) {
    if(errorEl) {
      errorEl.textContent = err.message || 'Registration failed';
      errorEl.style.display = 'block';
    }
  }
}

function logout(){
  window.api.setAuthToken(null);
  window.api.setCurrentUser(null);
  isLoggedIn = false;
  currentUser = null;
  document.getElementById('loggedOutActions').style.display = 'inline-flex';
  document.getElementById('loggedInActions').style.display = 'none';
  goTo('home');
}

/* ===== PASSWORD TOGGLE ===== */
function togglePass(id, btn){
  const input = document.getElementById(id);
  const icon = btn.querySelector('i');
  if(input.type==='password'){ input.type='text'; icon.className='fa-solid fa-eye-slash'; }
  else { input.type='password'; icon.className='fa-solid fa-eye'; }
}
function checkMatch(){
  const p1 = document.getElementById('regPass').value;
  const p2 = document.getElementById('regPass2').value;
  document.getElementById('matchError').style.display = (p2 && p1!==p2) ? 'block':'none';
}

/* ===== IMAGE PREVIEW ===== */
function previewImage(e){
  const file = e.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = function(ev){
    document.getElementById('uploadPreview').innerHTML = `<img src="${ev.target.result}" style="max-height:160px;border-radius:10px;margin:0 auto;"><p style="margin-top:10px;"><span>${file.name}</span></p>`;
  };
  reader.readAsDataURL(file);
}

/* ===== SUBMIT REPORT ===== */
async function submitReport(e){
  e.preventDefault();
  const form = e.target;
  const formData = new FormData();

  const titleEl = document.getElementById('reportTitle') || form.querySelector('[name="title"]');
  const catEl = document.getElementById('reportCategory') || form.querySelector('[name="category"]');
  const sevEl = document.getElementById('reportSeverity') || form.querySelector('[name="severity"]');
  const locEl = document.getElementById('reportLocation') || form.querySelector('[name="location"]');
  const descEl = document.getElementById('reportDescription') || form.querySelector('[name="description"]');
  const fileEl = document.getElementById('reportPhoto') || form.querySelector('[type="file"]');

  if (titleEl) formData.append('title', titleEl.value);
  if (catEl) formData.append('category', catEl.value);
  if (sevEl) formData.append('severity', sevEl.value);
  if (locEl) formData.append('location', locEl.value);
  if (descEl) formData.append('description', descEl.value);
  if (fileEl && fileEl.files[0]) formData.append('photo', fileEl.files[0]);

  try {
    await window.api.createReport(formData);
    const toast = document.getElementById('successToast');
    if (toast) {
      toast.classList.add('show');
      setTimeout(()=>toast.classList.remove('show'), 3500);
    }
    if (typeof renderReports === 'function') renderReports();
    setTimeout(()=>goTo('reports'), 700);
  } catch (err) {
    alert(err.message || 'Failed to submit report. Please check required fields.');
  }
}

